content:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400&family=Noto+Sans+JP:wght@300;400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;1,400&display=swap');

:root {
  --color-bg: #faf7f2;
  --color-bg-card: #ffffff;
  --color-bg-soft: #f4eee5;
  --color-primary: #5c3d2e;
  --color-primary-dark: #3f271c;
  --color-primary-light: #835b45;
  --color-accent: #c48b5c;
  --color-accent-light: #e8d7c8;
  --color-accent-gold: #b38b4d;
  --color-text-main: #2b2523;
  --color-text-muted: #6b635e;
  --color-text-light: #9c928b;
  --color-border: #e6ded3;
  --color-border-subtle: #efe9e0;
  --color-tag-bg: #ece5dc;

  --shadow-sm: 0 2px 8px rgba(92, 61, 46, 0.05);
  --shadow-md: 0 8px 24px rgba(92, 61, 46, 0.08);
  --shadow-lg: 0 16px 36px rgba(92, 61, 46, 0.12);
  --shadow-xl: 0 24px 48px rgba(92, 61, 46, 0.18);

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 22px;
  --radius-pill: 9999px;

  --font-serif: 'Playfair Display', 'Cormorant Garamond', serif;
  --font-sans: 'Noto Sans JP', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --transition: all 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  background-color: var(--color-bg);
}

body {
  font-family: var(--font-sans);
  color: var(--color-text-main);
  background-color: var(--color-bg);
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, select, textarea {
  font-family: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

/* ==========================================================================
   Base App Shell & Layout
   ========================================================================== */
.cafe-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
  background-color: var(--color-bg);
}

/* ==========================================================================
   Navbar & Mobile Navigation
   ========================================================================== */
.navbar {
  position: sticky;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 2.5rem;
  background-color: rgba(250, 247, 242, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  transition: var(--transition);
}

.nav-brand {
  font-family: var(--font-serif);
  font-size: 1.55rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--color-primary-dark);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
  z-index: 102;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
  list-style: none;
}

.nav-link {
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--color-text-main);
  padding: 0.4rem 0.2rem;
  position: relative;
  transition: var(--transition);
  cursor: pointer;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width 0.25s ease;
}

.nav-link:hover {
  color: var(--color-primary);
}

.nav-link:hover::after {
  width: 100%;
}

.nav-reserve-btn {
  background-color: var(--color-primary);
  color: #ffffff;
  padding: 0.55rem 1.4rem;
  font-size: 0.9rem;
  font-weight: 500;
  border-radius: var(--radius-pill);
  border: 1px solid var(--color-primary);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  box-shadow: 0 4px 12px rgba(92, 61, 46, 0.15);
}

.nav-reserve-btn:hover {
  background-color: var(--color-primary-dark);
  box-shadow: 0 6px 16px rgba(92, 61, 46, 0.22);
  transform: translateY(-1px);
}

/* ハンバーガーボタンスタイル */
.nav-toggle {
  display: none;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  z-index: 102;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.nav-toggle-bar {
  width: 22px;
  height: 2px;
  background-color: var(--color-primary-dark);
  border-radius: 2px;
  transition: var(--transition);
}

.nav-toggle.active .nav-toggle-bar:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.nav-toggle.active .nav-toggle-bar:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active .nav-toggle-bar:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* モバイルドロワーメニュー */
.nav-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 280px;
  height: 100vh;
  background-color: var(--color-bg);
  box-shadow: var(--shadow-xl);
  padding: 6rem 2rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  transition: right 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 101;
  border-left: 1px solid var(--color-border);
}

.nav-drawer.open {
  right: 0;
}

.nav-drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(43, 37, 35, 0.45);
  backdrop-filter: blur(4px);
  z-index: 100;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.nav-drawer-backdrop.open {
  opacity: 1;
  pointer-events: auto;
}

/* ==========================================================================
   Hero Section
   ========================================================================== */
.hero-section {
  position: relative;
  min-height: 86vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 5rem 2rem;
  background: linear-gradient(180deg, rgba(250, 247, 242, 0.82) 0%, rgba(244, 238, 229, 0.92) 100%),
              url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1920&q=80') center/cover no-repeat;
  text-align: center;
}

.hero-content {
  max-width: 820px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  animation: fadeIn 0.8s ease-out;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 1.1rem;
  background-color: rgba(255, 255, 255, 0.85);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  font-size: 0.82rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: 1.5rem;
  box-shadow: var(--shadow-sm);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  font-weight: 600;
  line-height: 1.25;
  color: var(--color-primary-dark);
  letter-spacing: 0.03em;
  margin-bottom: 1.2rem;
}

.hero-subtitle {
  font-size: clamp(1rem, 1.8vw, 1.2rem);
  color: var(--color-text-muted);
  line-height: 1.85;
  max-width: 640px;
  margin-bottom: 2.5rem;
}

.hero-btn-group {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.2rem;
  flex-wrap: wrap;
}

/* ==========================================================================
   Buttons
   ========================================================================== */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.85rem 2rem;
  background-color: var(--color-primary);
  color: #ffffff;
  border-radius: var(--radius-pill);
  font-size: 0.95rem;
  font-weight: 600;
  border: 1px solid var(--color-primary);
  cursor: pointer;
  transition: var(--transition);
  box-shadow: 0 4px 14px rgba(92, 61, 46, 0.2);
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(92, 61, 46, 0.28);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.85rem 2rem;
  background-color: rgba(255, 255, 255, 0.8);
  color: var(--color-primary-dark);
  border-radius: var(--radius-pill);
  font-size: 0.95rem;
  font-weight: 600;
  border: 1.5px solid var(--color-primary-light);
  cursor: pointer;
  transition: var(--transition);
  backdrop-filter: blur(6px);
}

.btn-outline:hover {
  background-color: #ffffff;
  color: var(--color-primary);
  border-color: var(--color-primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.btn-outline:active {
  transform: translateY(0);
}

/* ==========================================================================
   Section Common
   ========================================================================== */
.section-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 3.5vw, 2.75rem);
  color: var(--color-primary-dark);
  text-align: center;
  letter-spacing: 0.05em;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.section-subtitle {
  text-align: center;
  font-size: 0.95rem;
  color: var(--color-text-muted);
  letter-spacing: 0.06em;
  margin-bottom: 3.5rem;
}

/* ==========================================================================
   Concept Section
   ========================================================================== */
.concept-section {
  padding: 6.5rem 2rem;
  background-color: #ffffff;
  position: relative;
}

.concept-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2.2rem;
}

.concept-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 2.75rem 2rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.concept-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent-light);
}

.concept-icon {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  background-color: var(--color-bg-soft);
  color: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.6rem;
  transition: var(--transition);
}

.concept-card:hover .concept-icon {
  background-color: var(--color-primary);
  color: #ffffff;
}

.concept-card-title {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  color: var(--color-primary-dark);
  font-weight: 600;
  margin-bottom: 1rem;
}

.concept-card-desc {
  font-size: 0.94rem;
  color: var(--color-text-muted);
  line-height: 1.8;
}

/* ==========================================================================
   Menu Section
   ========================================================================== */
.menu-section {
  padding: 6.5rem 2rem;
  background-color: var(--color-bg);
  position: relative;
}

.menu-tabs {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 3.5rem;
}

.menu-tab-btn {
  background: #ffffff;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
  padding: 0.65rem 1.6rem;
  border-radius: var(--radius-pill);
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.menu-tab-btn:hover {
  color: var(--color-primary);
  border-color: var(--color-primary-light);
  background: #ffffff;
}

.menu-tab-btn-active {
  background-color: var(--color-primary);
  color: #ffffff;
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(92, 61, 46, 0.16);
}

.menu-tab-btn-active:hover {
  background-color: var(--color-primary-dark);
  color: #ffffff;
  border-color: var(--color-primary-dark);
}

.menu-grid {
  max-width: 1240px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

.menu-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border-subtle);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: var(--transition);
}

.menu-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.menu-img-wrap {
  position: relative;
  width: 100%;
  padding-top: 68%;
  overflow: hidden;
  background-color: var(--color-bg-soft);
}

.menu-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.menu-card:hover .menu-img {
  transform: scale(1.05);
}

.menu-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  background: rgba(196, 139, 92, 0.95);
  color: #ffffff;
  font-size: 0.72rem;
  letter-spacing: 0.05em;
  padding: 0.28rem 0.75rem;
  border-radius: var(--radius-pill);
  font-weight: 600;
  backdrop-filter: blur(4px);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.menu-body {
  padding: 1.4rem 1.4rem 1.6rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.menu-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.75rem;
  margin-bottom: 0.6rem;
}

.menu-name {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--color-primary-dark);
}

.menu-price {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-accent);
  white-space: nowrap;
}

.menu-desc {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  line-height: 1.65;
  margin-top: auto;
}

/* ==========================================================================
   Access & Store Info Section
   ========================================================================== */
.access-section {
  padding: 6.5rem 2rem;
  background-color: #ffffff;
  position: relative;
}

.access-container {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.access-info-card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 2.5rem;
  box-shadow: var(--shadow-sm);
}

.access-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 2rem;
}

.access-table tr {
  border-bottom: 1px solid var(--color-border-subtle);
}

.access-table tr:last-child {
  border-bottom: none;
}

.access-table th {
  text-align: left;
  padding: 1rem 0;
  width: 32%;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--color-primary);
  vertical-align: top;
}

.access-table td {
  padding: 1rem 0;
  font-size: 0.92rem;
  color: var(--color-text-main);
  line-height: 1.6;
}

.facility-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-top: 1.2rem;
  padding-top: 1.2rem;
  border-top: 1px dashed var(--color-border);
}

.facility-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.35rem 0.85rem;
  background-color: var(--color-tag-bg);
  border-radius: var(--radius-pill);
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--color-primary-dark);
}

.access-map-mock {
  position: relative;
  min-height: 440px;
  height: 100%;
  border-radius: var(--radius-md);
  background: #e9e4dc url('https://images.unsplash.com/photo-1524661135-423995f22d0b?auto=format&fit=crop&w=1200&q=80') center/cover no-repeat;
  overflow: hidden;
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
}

.access-map-mock::before {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(43, 37, 35, 0.28);
}

.map-pin {
  position: relative;
  z-index: 2;
  background-color: #ffffff;
  padding: 0.9rem 1.4rem;
  border-radius: var(--radius-pill);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--color-primary-dark);
  animation: floatPin 2.6s ease-in-out infinite alternate;
}

/* ==========================================================================
   Reservation Modal
   ========================================================================== */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(43, 37, 35, 0.65);
  backdrop-filter: blur(6px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  animation: fadeIn 0.25s ease-out;
}

.modal-container {
  background-color: #ffffff;
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 580px;
  max-height: 92vh;
  overflow-y: auto;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--color-border);
  position: relative;
  animation: scaleUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.modal-header {
  padding: 1.8rem 2rem 1.2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--color-border-subtle);
}

.modal-title {
  font-family: var(--font-serif);
  font-size: 1.45rem;
  font-weight: 600;
  color: var(--color-primary-dark);
}

.modal-close-btn {
  background: transparent;
  border: none;
  font-size: 1.5rem;
  color: var(--color-text-muted);
  cursor: pointer;
  padding: 0.3rem;
  line-height: 1;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.modal-close-btn:hover {
  color: var(--color-text-main);
  background-color: var(--color-bg-soft);
}

.modal-body {
  padding: 1.8rem 2rem;
}

.form-group {
  margin-bottom: 1.2rem;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.form-label {
  display: block;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--color-text-main);
  margin-bottom: 0.4rem;
}

.form-input,
.form-select {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: var(--color-bg);
  font-size: 0.95rem;
  color: var(--color-text-main);
  transition: var(--transition);
  outline: none;
}

.form-input:focus,
.form-select:focus {
  border-color: var(--color-primary);
  background-color: #ffffff;
  box-shadow: 0 0 0 3px rgba(92, 61, 46, 0.12);
}

.modal-footer {
  padding: 1.2rem 2rem 1.8rem;
  border-top: 1px solid var(--color-border-subtle);
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 1rem;
}

/* ==========================================================================
   Toast Notification
   ========================================================================== */
.toast-notification {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 1100;
  background-color: var(--color-primary-dark);
  color: #ffffff;
  padding: 1rem 1.6rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.92rem;
  animation: slideInUp 0.35s ease-out;
}

/* ==========================================================================
   Footer
   ========================================================================== */
.footer {
  background-color: var(--color-primary-dark);
  color: #ded6cc;
  padding: 4.5rem 2rem 2rem;
  margin-top: auto;
}

.footer-content {
  max-width: 1200px;
  margin: 0 auto;
  text-align: center;
}

.footer-text {
  font-size: 0.88rem;
  color: #a89f94;
  letter-spacing: 0.05em;
  margin-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 2rem;
}

/* ==========================================================================
   Animations & Responsive Breakpoints
   ========================================================================== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scaleUp {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes slideInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes floatPin {
  from { transform: translateY(0); }
  to { transform: translateY(-8px); }
}

@media (max-width: 900px) {
  .access-container {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .access-map-mock {
    min-height: 320px;
  }
}

@media (max-width: 768px) {
  .navbar {
    padding: 0 1rem;
    height: 64px;
    position: sticky;
    top: 0;
    flex-wrap: wrap;
    justify-content: space-between;
  }

  .nav-brand {
    font-size: 1.35rem;
  }

  .nav-toggle {
    display: flex;
  }

  /* モバイル表示時のナビゲーション回遊性を確保 */
  .nav-links {
    display: flex;
    position: static;
    width: 100%;
    order: 3;
    justify-content: center;
    gap: 1.2rem;
    padding: 0.5rem 0 0.2rem;
    border-top: 1px solid var(--color-border-subtle);
    background-color: transparent;
  }

  .nav-link {
    font-size: 0.82rem;
    padding: 0.25rem 0.4rem;
  }

  .nav-reserve-btn {
    padding: 0.45rem 1rem;
    font-size: 0.82rem;
  }

  .access-table,
  .access-table tbody,
  .access-table tr,
  .access-table th,
  .access-table td {
    display: block;
    width: 100%;
  }

  .access-table tr {
    padding: 0.75rem 0;
  }

  .access-table th {
    width: 100%;
    padding: 0 0 0.25rem 0;
    font-size: 0.88rem;
  }

  .access-table td {
    padding: 0;
    font-size: 0.88rem;
  }

  .hero-section {
    min-height: 75vh;
    padding: 4rem 1.25rem;
  }

  .concept-section,
  .menu-section,
  .access-section {
    padding: 4.5rem 1.25rem;
  }

  .section-subtitle {
    margin-bottom: 2.5rem;
  }

  .form-row {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .modal-container {
    max-height: 95vh;
  }

  .modal-header,
  .modal-body,
  .modal-footer {
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }

  .toast-notification {
    left: 1.25rem;
    right: 1.25rem;
    bottom: 1.25rem;
    text-align: center;
    justify-content: center;
  }
}

/* ==========================================================================
   Accessibility: Reduced Motion
   ========================================================================== */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .map-pin {
    animation: none;
  }

  .hero-content,
  .modal-backdrop,
  .modal-container,
  .toast-notification {
    animation: none;
  }
}

