const FALLBACK_IMAGE = 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=600&q=80';

type TabType = 'all' | MenuCategory;

interface MenuSectionProps {
  items?: MenuItem[];
}

export default function MenuSection({ items = MENU_ITEMS }: MenuSectionProps) {
  const [activeTab, setActiveTab] = useState<TabType>('all');

  const filteredItems = activeTab === 'all'
    ? items
    : items.filter((item) => item.category === activeTab);

  const getCount = (category: TabType) => {
    if (category === 'all') return items.length;
    return items.filter((item) => item.category === category).length;
  };

  const handleImageError = (e: SyntheticEvent<HTMLImageElement, Event>) => {
    e.currentTarget.onerror = null;
    e.currentTarget.src = FALLBACK_IMAGE;
  };

  return (
    <section className="menu-section" id="menu">
      <h2 className="section-title">Seasonal & Signature Menu</h2>
      <p className="section-subtitle">
        丁寧な手仕事と厳選した素材が織りなす、心ほどける特別な一杯と一皿
      </p>

      <div className="menu-tabs">
        <button
          type="button"
          className={activeTab === 'all' ? 'menu-tab-btn menu-tab-btn-active' : 'menu-tab-btn'}
          onClick={() => setActiveTab('all')}
        >
          <Sparkles size={16} /> 全メニュー
          <span style={{ fontSize: '0.8rem', opacity: 0.85, marginLeft: '0.2rem' }}>
            ({getCount('all')})
          </span>
        </button>
        <button
          type="button"
          className={activeTab === 'coffee' ? 'menu-tab-btn menu-tab-btn-active' : 'menu-tab-btn'}
          onClick={() => setActiveTab('coffee')}
        >
          <Coffee size={16} /> 珈琲
          <span style={{ fontSize: '0.8rem', opacity: 0.85, marginLeft: '0.2rem' }}>
            ({getCount('coffee')})
          </span>
        </button>
        <button
          type="button"
          className={activeTab === 'drink' ? 'menu-tab-btn menu-tab-btn-active' : 'menu-tab-btn'}
          onClick={() => setActiveTab('drink')}
        >
          <Wine size={16} /> ドリンク
          <span style={{ fontSize: '0.8rem', opacity: 0.85, marginLeft: '0.2rem' }}>
            ({getCount('drink')})
          </span>
        </button>
        <button
          type="button"
          className={activeTab === 'sweets' ? 'menu-tab-btn menu-tab-btn-active' : 'menu-tab-btn'}
          onClick={() => setActiveTab('sweets')}
        >
          <CakeSlice size={16} /> スイーツ
          <span style={{ fontSize: '0.8rem', opacity: 0.85, marginLeft: '0.2rem' }}>
            ({getCount('sweets')})
          </span>
        </button>
        <button
          type="button"
          className={activeTab === 'food' ? 'menu-tab-btn menu-tab-btn-active' : 'menu-tab-btn'}
          onClick={() => setActiveTab('food')}
        >
          <UtensilsCrossed size={16} /> フード
          <span style={{ fontSize: '0.8rem', opacity: 0.85, marginLeft: '0.2rem' }}>
            ({getCount('food')})
          </span>
        </button>
      </div>

      <div className="menu-grid">
        {filteredItems.map((item) => (
          <article key={item.id} className="menu-card">
            <div className="menu-img-wrap">
              <img
                src={item.image}
                alt={item.name}
                className="menu-img"
                loading="lazy"
                onError={handleImageError}
              />
              {item.isRecommended && (
                <span className="menu-badge">おすすめ</span>
              )}
            </div>
            <div className="menu-body">
              <div className="menu-header">
                <h3 className="menu-name">{item.name}</h3>
                <span className="menu-price">
                  ¥{item.price.toLocaleString()}
                  <span style={{ fontSize: '0.78rem', fontWeight: 500, marginLeft: '0.2rem', color: 'var(--color-text-muted)' }}>
                    (税込)
                  </span>
                </span>
              </div>
              <p className="menu-desc">{item.description}</p>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

