import { useState, useEffect, FormEvent } from 'react';
import { X, Calendar, Clock, Users, Armchair, Phone, Mail, User } from 'lucide-react';
import { ReservationFormValues, SeatType } from '../types';

interface ExtendedReservationFormValues extends ReservationFormValues {
  tel: string;
}

interface ReservationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccessNotice?: (message: string) => void;
}

const INITIAL_FORM: ExtendedReservationFormValues = {
  name: '',
  email: '',
  tel: '',
  date: '',
  time: '14:00',
  guests: 2,
  seatType: 'table',
  note: '',
};

export default function ReservationModal({ isOpen, onClose, onSuccessNotice }: ReservationModalProps) {
  const [formData, setFormData] = useState<ExtendedReservationFormValues>(INITIAL_FORM);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    setTimeout(() => {
      setIsSubmitting(false);
      const noticeText = `${formData.name} 様、${formData.date} ${formData.time}（${formData.guests}名様）の仮予約を受付いたしました。確認メールおよびお電話（${formData.tel}）にてご連絡いたします。`;
      onSuccessNotice?.(noticeText);
      setFormData(INITIAL_FORM);
      onClose();
    }, 600);
  };

  const todayStr = new Date().toISOString().split('T')[0];

  return (
    <div className="modal-backdrop" onClick={onClose} role="dialog" aria-modal="true">
      <div className="modal-container" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h3 className="modal-title">お席のWeb仮予約・お問い合わせ</h3>
          <button
            type="button"
            className="modal-close-btn"
            onClick={onClose}
            aria-label="閉じる"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            <div className="form-group">
              <label className="form-label" htmlFor="res-name" style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                <User size={15} color="#5c3d2e" />
                <span>お名前</span> <span style={{ color: '#c48b5c' }}>*</span>
              </label>
              <input
                id="res-name"
                type="text"
                required
                placeholder="例: 山田 花子"
                className="form-input"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              />
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label" htmlFor="res-email" style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                  <Mail size={15} color="#5c3d2e" />
                  <span>メールアドレス</span> <span style={{ color: '#c48b5c' }}>*</span>
                </label>
                <input
                  id="res-email"
                  type="email"
                  required
                  placeholder="例: lumiere@example.com"
                  className="form-input"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="res-tel" style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                  <Phone size={15} color="#5c3d2e" />
                  <span>お電話番号</span> <span style={{ color: '#c48b5c' }}>*</span>
                </label>
                <input
                  id="res-tel"
                  type="tel"
                  required
                  placeholder="例: 090-1234-5678"
                  className="form-input"
                  value={formData.tel}
                  onChange={(e) => setFormData({ ...formData, tel: e.target.value })}
                />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label" htmlFor="res-date" style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                  <Calendar size={15} color="#5c3d2e" />
                  <span>希望日</span> <span style={{ color: '#c48b5c' }}>*</span>
                </label>
                <input
                  id="res-date"
                  type="date"
                  required
                  min={todayStr}
                  className="form-input"
                  value={formData.date}
                  onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="res-time" style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                  <Clock size={15} color="#5c3d2e" />
                  <span>希望時間帯</span> <span style={{ color: '#c48b5c' }}>*</span>
                </label>
                <select
                  id="res-time"
                  className="form-select"
                  value={formData.time}
                  onChange={(e) => setFormData({ ...formData, time: e.target.value })}
                >
                  <option value="09:00">09:00 - 朝の穏やかなひととき</option>
                  <option value="11:30">11:30 - ランチタイム</option>
                  <option value="14:00">14:00 - カフェ＆スイーツ</option>
                  <option value="16:00">16:00 - アフタヌーン</option>
                  <option value="18:00">18:00 - イブニングカフェ</option>
                  <option value="19:30">19:30 - ディナー＆バータイム</option>
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label" htmlFor="res-guests" style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                  <Users size={15} color="#5c3d2e" />
                  <span>ご利用人数</span> <span style={{ color: '#c48b5c' }}>*</span>
                </label>
                <select
                  id="res-guests"
                  className="form-select"
                  value={formData.guests}
                  onChange={(e) => setFormData({ ...formData, guests: Number(e.target.value) })}
                >
                  <option value={1}>1名様</option>
                  <option value={2}>2名様</option>
                  <option value={3}>3名様</option>
                  <option value={4}>4名様</option>
                  <option value={5}>5名様以上（要ご相談）</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="res-seat" style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                  <Armchair size={15} color="#5c3d2e" />
                  <span>ご希望の座席タイプ</span> <span style={{ color: '#c48b5c' }}>*</span>
                </label>
                <select
                  id="res-seat"
                  className="form-select"
                  value={formData.seatType}
                  onChange={(e) => setFormData({ ...formData, seatType: e.target.value as SeatType })}
                >
                  <option value="table">テーブル席（ゆったり会話に）</option>
                  <option value="counter">カウンター席（お一人様・作業に）</option>
                  <option value="terrace">テラス席（心地よい外風と緑）</option>
                </select>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="res-note">
                ご要望・アレルギー等（任意）
              </label>
              <textarea
                id="res-note"
                rows={3}
                placeholder="アレルギーやお祝いプレートのご相談など、お気軽にご記入ください。"
                className="form-input"
                style={{ resize: 'vertical' }}
                value={formData.note}
                onChange={(e) => setFormData({ ...formData, note: e.target.value })}
              />
            </div>
          </div>

          <div className="modal-footer">
            <button type="button" className="btn-outline" onClick={onClose} disabled={isSubmitting}>
              キャンセル
            </button>
            <button type="submit" className="btn-primary" disabled={isSubmitting}>
              {isSubmitting ? '送信中...' : '仮予約をリクエストする'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

